@import url('https://fonts.googleapis.com/css2?family=inter:wght@400;600;700&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  overflow-x: hidden;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #F5F5F5;
  font-family: "Inter", sans-serif;
}

#ad-320x480 {
  width: 320px;
  min-width: 320px;
  max-width: 320px;
  height: 480px;
  min-height: 480px;
  max-height: 480px;
  background: #FFFFFF;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
  flex-shrink: 0;
}

/* ── HEADER ── */
.ad-header {
  background: #0058AB;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  flex-shrink: 0;
  height: 44px;
}

.ad-logo {
  height: 28px;
  width: auto;
  display: block;
  max-height: 32px;
}

.eyebrow {
  font-family: "Inter", sans-serif;
  font-weight: 600;
  font-size: 10px;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: #FBD914;
}

/* ── CAROUSEL ── */
.carousel-wrapper {
  position: relative;
  width: 320px;
  height: 188px;
  flex-shrink: 0;
  overflow: hidden;
  background: #F5F5F5;
}

.carousel-track {
  display: flex;
  width: 300%;
  height: 100%;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
  will-change: transform;
}

.carousel-slide {
  width: calc(320px);
  height: 188px;
  position: relative;
  overflow: hidden;
  flex-shrink: 0;
}

.slide-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
  transition: transform 0.6s ease;
}

.slide-img.product {
  object-fit: contain;
  background: #F5F5F5;
  padding: 8px;
}

.slide-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  background: #FBD914;
  color: #111111;
  font-family: "Inter", sans-serif;
  font-weight: 700;
  font-size: 9px;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 2px;
}

/* Dots */
.carousel-dots {
  position: absolute;
  bottom: 8px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 4px;
  z-index: 10;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: none;
  background: rgba(255,255,255,0.6);
  cursor: pointer;
  padding: 0;
  transition: background 0.3s, transform 0.3s;
}

.dot.active {
  background: #FBD914;
  transform: scale(1.3);
}

/* ── COPY BLOCK ── */
.copy-block {
  padding: 10px 14px 6px;
  flex-shrink: 0;
  background: #FFFFFF;
}

.headline {
  font-family: "Inter", sans-serif;
  font-weight: 700;
  font-size: 20px;
  color: #111111;
  line-height: 1.15;
  margin-bottom: 2px;
}

.headline em {
  font-style: normal;
  color: #0058AB;
}

.subhead {
  font-family: "Inter", sans-serif;
  font-weight: 600;
  font-size: 11px;
  color: #0058AB;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  margin-bottom: 4px;
}

.body-copy {
  font-family: "Inter", sans-serif;
  font-weight: 400;
  font-size: 11px;
  color: #484848;
  line-height: 1.45;
}

/* ── THUMBNAIL STRIP ── */
.thumb-strip {
  display: flex;
  gap: 6px;
  padding: 8px 12px;
  background: #F5F5F5;
  border-top: 1px solid rgba(0,0,0,0.06);
  flex-shrink: 0;
  overflow-x: auto;
  scrollbar-width: none;
}

.thumb-strip::-webkit-scrollbar {
  display: none;
}

.thumb-btn {
  width: 48px;
  height: 48px;
  border-radius: 4px;
  border: 2px solid transparent;
  overflow: hidden;
  flex-shrink: 0;
  cursor: pointer;
  padding: 0;
  background: #FFFFFF;
  transition: border-color 0.25s, transform 0.2s;
  outline: none;
}

.thumb-btn img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.thumb-btn.active {
  border-color: #0058AB;
  transform: scale(1.08);
}

.thumb-btn:hover {
  border-color: #FBD914;
  transform: scale(1.08);
}

/* ── FOOTER / CTA ── */
.ad-footer {
  background: #003E7E;
  padding: 10px 14px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
  margin-top: auto;
}

.cta-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #0058AB;
  color: #FFFFFF;
  text-decoration: none;
  border-radius: 3px;
  padding: 9px 28px;
  width: 100%;
  margin-bottom: 0;
  transition: background 0.2s, transform 0.15s;
}

.cta-btn:hover {
  background: #003E7E;
  transform: translateY(-1px);
}

.cta-label {
  font-family: "Inter", sans-serif;
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: #FFFFFF;
}

.ad-footer span {
  font-family: "Inter", sans-serif;
  font-weight: 400;
  font-size: 9px;
  color: rgba(255,255,255,0.55);
  letter-spacing: 0.3px;
}

/* ── REDUCED MOTION ── */
@media (prefers-reduced-motion: reduce) {
  .carousel-track {
    transition: none;
  }
  .slide-img {
    transition: none;
  }
  .cta-btn {
    transition: none;
  }
}

